def _with_proofs(rs):
    for r in rs:
        if r['id'] in PROOF and not r.get('proof'):
            r['proof'] = PROOF[r['id']]
    return rs


def rows(inv):  # noqa: F811 (the final definition)
    out = CURATED + generated(inv)
    for r in out:
        if r['id'].startswith('pol.law.'):
            r['proof'] = {'politics_choose': {'category': 'government|economy'}}
        if r['id'].startswith('res.doctrine.'):
            r['proof'] = {'doctrine_adopt': {}}
        if r['id'].startswith('int.branch.'):
            r['proof'] = {'agency_upgrade': {}}
    return _with_proofs(out)

